import{_ as i,c as t,o as a,ag as n}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"nPlyr","text":"不只是播放的影片播放器","tagline":"基於 AVFoundation 打造的 macOS 與 iOS 原生播放器。內建嗅探器擷取任意網站的影片串流，還能執行小程式。","image":{"src":"/hero-illustration.png","alt":"nPlyr"},"actions":[{"theme":"brand","text":"開始使用","link":"/zh-TW/guide/installation"},{"theme":"alt","text":"小程式","link":"/zh-TW/guide/miniapps"}]},"features":[{"icon":{"light":"/icons/layers.svg","dark":"/icons/layers-dark.svg","alt":"播放器","width":"24","height":"24"},"title":"原生播放器","details":"macOS 與 iOS 共用一套基於 AVFoundation（AVPlayer）的播放核心。支援 HLS/m3u8、MP4、FLV、TS 等格式，並具備字幕、音軌、倍速、畫中畫與 AirPlay。","link":"/zh-TW/guide/player","linkText":"深入了解"},{"icon":{"light":"/icons/zap.svg","dark":"/icons/zap-dark.svg","alt":"嗅探器","width":"24","height":"24"},"title":"內建嗅探器","details":"一個 Chrome 風格的多分頁瀏覽器，會向每個頁面注入媒體偵測腳本，將 m3u8/mp4/flv/ts 直鏈及其請求標頭匯總到一個抽屜中。","link":"/zh-TW/guide/browser","linkText":"運作原理"},{"icon":{"light":"/icons/sparkles.svg","dark":"/icons/sparkles-dark.svg","alt":"小程式","width":"24","height":"24"},"title":"小程式執行環境","details":"原生執行與 hikerView 相容的小程式與規則——同一套規則 DSL 與 fy_bridge_app 契約，在 Apple 平台重新實作。瀏覽社群資源目錄。","link":"/zh-TW/guide/miniapps","linkText":"探索執行環境"},{"icon":{"light":"/icons/camera.svg","dark":"/icons/camera-dark.svg","alt":"下載","width":"24","height":"24"},"title":"下載與邊下邊播","details":"將 HLS 播放清單下載為 MP4，或在檔案仍在下載時就開始觀看（邊下邊播）。支援多清晰度與字幕下載。","link":"/zh-TW/guide/downloads","linkText":"下載指南"},{"icon":{"light":"/icons/eye.svg","dark":"/icons/eye-dark.svg","alt":"媒體庫","width":"24","height":"24"},"title":"媒體庫","details":"觀看歷程、書籤與下載內容統一收納在一個可搜尋的媒體庫中，並在你的 Mac 與 iPhone 之間同步。","link":"/zh-TW/guide/downloads","linkText":"開啟媒體庫"},{"icon":{"light":"/icons/frame.svg","dark":"/icons/frame-dark.svg","alt":"主題","width":"24","height":"24"},"title":"主題與 25 種語言","details":"在內建主題之間切換，或自訂屬於你的主題。整個介面已在地化為 25 種語言，並在兩個平台上跟隨系統外觀。","link":"/zh-TW/guide/settings","linkText":"個人化"}],"floatingCards":["原生 AVFoundation 核心","無多餘負擔","嗅探器 + 瀏覽器","小程式執行環境"],"sections":{"featuresTitle":"核心功能","featuresSubtitle":"在 Apple 平台上播放、擷取與整理影片所需的一切","categoriesTitle":"你能做什麼","categoriesSubtitle":"一個應用程式，集播放器、瀏覽器與小程式執行環境於一身","howTitle":"運作原理","howSubtitle":"開箱即用、協同運作的三大組成","faqTitle":"常見問題","faqSubtitle":"針對 macOS 與 iOS 使用者的快速解答"},"openMarketplace":"瀏覽小程式","cta":{"title":"準備好播放任何內容了嗎？","description":"下載 nPlyr，把任意網頁變成可播放的影片串流——原生執行於你的 Mac 與 iPhone，由 AVFoundation 驅動。","primary":"開始使用","primaryLink":"/guide/installation","secondary":"使用指南","secondaryLink":"/guide/player"},"categories":[{"name":"觀看","badge":"PL","desc":"播放本機檔案、URL 與串流","color":"#ef6400"},{"name":"擷取","badge":"SN","desc":"從網頁嗅探直鏈","color":"#2563eb"},{"name":"擴充","badge":"MP","desc":"執行 hikerView 小程式","color":"#059669"},{"name":"儲存","badge":"DL","desc":"下載並整理媒體","color":"#7c3aed"},{"name":"同步","badge":"LB","desc":"跨裝置媒體庫","color":"#d97706"},{"name":"個人化","badge":"TH","desc":"主題與 25 種語言","color":"#0891b2"}],"steps":[{"num":"01","title":"安裝並啟動","desc":"從 Mac App Store 取得 nPlyr，或側載 iOS 版本，然後從 Dock 或主畫面啟動。"},{"num":"02","title":"開啟一個影片","desc":"將檔案拖入主播放器，或貼上連結，也可以使用內建瀏覽器尋找影片串流。"},{"num":"03","title":"擷取與擴充","desc":"一鍵嗅探直鏈，或打開社群小程式，瀏覽整個影片來源。"}],"faqs":[{"question":"nPlyr 免費嗎？","answer":"nPlyr 在 App Store 上是付費應用程式。免費層級可試用核心播放器與有限數量的小程式；解鎖後取消小程式數量限制。沒有帳號體系，也沒有遙測。"},{"question":"支援哪些平台？","answer":"nPlyr 支援 macOS 14 Sonoma 及以上（針對 Apple Silicon 最佳化，同時支援 Intel），以及 iOS / iPadOS 16 及以上。兩個平台共用同一套播放核心。"},{"question":"它使用了 ffmpeg 或其他外部二進位嗎？","answer":"沒有。播放與重新封裝核心完全基於 Apple 的 AVFoundation（AVPlayer）建構。這讓應用程式保持輕量、沙盒友善並符合 App Store 規範。"},{"question":"支援哪些影片格式？","answer":"由於依賴 AVFoundation，nPlyr 可播放作業系統原生解碼的一切格式——HLS（m3u8）、分片 MP4、MP4、MOV、M4V，以及 AVPlayer 可讀取的容器。對於 HLS，下載與重新封裝為 MP4 均在應用程式內完成。"},{"question":"什麼是小程式，它們安全嗎？","answer":"小程式是 hikerView 相容的規則，讓 nPlyr 透過沙盒化的 JavaScript 引擎瀏覽並解析第三方影片來源。它們由社群提供。具體哪些 Java/Rhino 行為被支援、哪些不被支援，請參閱相容性頁面。"},{"question":"嗅探器在所有網站都能用嗎？","answer":"嗅探器會擷取頁面發起的媒體請求（fetch/XHR/video.src/MediaSource）。使用專有播放器或重度 DRM 包裹影片串流的網站可能不會暴露直鏈。對於這類來源，小程式執行環境是更可靠的路徑。"}]},"headers":[],"relativePath":"zh-TW/index.md","filePath":"zh-TW/index.md","lastUpdated":1791311600000}'),o={name:"zh-TW/index.md"};function l(r,e,s,d,c,g){return a(),t("div",null,[...e[0]||(e[0]=[n("",4)])])}const u=i(o,[["render",l]]);export{p as __pageData,u as default};
